+	res = yt921x_intif_ext_write(priv, addr, 0x3, 0x5603);
+	if (res)
+		return res;
+
+	msleep(20);
+	res = yt921x_intif_ext_write(priv, addr, 0x492, 0x7fff);
+	if (res)
+		return res;
+	res = yt921x_intif_ext_write(priv, addr, 0x492, 0x7f7f);
+	if (res)
+		return res;
+	/* CTLE */
+	res = yt921x_intif_ext_write(priv, addr, 0x2000, 0x40);
+	if (res)
+		return res;
+	res = yt921x_intif_ext_write(priv, addr, 0x2000, 0x0);
+	if (res)
+		return res;
+
+	if (interface == PHY_INTERFACE_MODE_SGMII) {
+		res = yt921x_intif_ext_write(priv, addr, 0x1042, 0x48c);
+		if (res)
+			return res;
+	}
+
+    /* soft reset */
+	addr = yt922x_internal_phyaddr_get(port, YT922X_PHY_REG_TYPE_MII,
+					   YT922X_PHY_REG_SPACE_SGMII);
+	if (addr < 0)
+		return res;
+	res = yt921x_intif_read(priv, addr, 0x2000, &data);
+	if (res)
+		return res;
+	data &= ~(1 << 15);
+	res = yt921x_intif_write(priv, addr, 0x2000, data);
+	if (res)
+		return res;
+	addr = yt922x_internal_phyaddr_get(port, YT922X_PHY_REG_TYPE_MII,
+					   YT922X_PHY_REG_SPACE_USXGMII);
+	if (addr < 0)
+		return res;
+	res = yt921x_intif_read(priv, addr, 0x0, &data);
+	if (res)
+		return res;
+	data |= 1 << 15;
+	res = yt921x_intif_write(priv, addr, 0x0, data);
+	if (res)
+		return res;
+
+	return 0;
+}
+
+static int
+yt922x_port_config(struct yt921x_priv *priv, int port, unsigned int mode,
+		   phy_interface_t interface)
+{
+	int addr;
+	u16 data;
+	int res;
+
+	addr = yt922x_internal_phyaddr_get(port,
+					   YT922X_PHY_REG_TYPE_SDS_COMMON_EXT,
+					   YT922X_PHY_REG_SPACE_SGMII);
+	if (addr < 0)
+		return -EINVAL;
+	switch (interface) {
+	/* SERDES */
+	case PHY_INTERFACE_MODE_SGMII:
+	case PHY_INTERFACE_MODE_100BASEX:
+	case PHY_INTERFACE_MODE_1000BASEX:
+	case PHY_INTERFACE_MODE_2500BASEX:
+	case PHY_INTERFACE_MODE_USXGMII:
+		res = yt922x_port_sds_init(priv, port, interface);
+		if (res)
+			return res;
+
+		addr = yt922x_internal_phyaddr_get
+			(port, YT922X_PHY_REG_TYPE_SDS_COMMON_EXT,
+			 YT922X_PHY_REG_SPACE_SGMII);
+		if (addr < 0)
+			return -EINVAL;
+
+		res = yt922x_intif_ext_read(priv, addr, YT922X_PORT_SDS_MODE,
+					    &data);
+		if (res)
+			return res;
+
+		data &= (~0x7 << 4);
+		switch (interface) {
+		case PHY_INTERFACE_MODE_SGMII:
+			data |= FIELD_PREP(YT922X_PORT_SDS_MODE_M,
+					   YT92XX_SERDES_MODE_SGMII);
+			break;
+		case PHY_INTERFACE_MODE_100BASEX:
+			data |= FIELD_PREP(YT922X_PORT_SDS_MODE_M,
+					   YT92XX_SERDES_MODE_100BASEX);
+			break;
+		case PHY_INTERFACE_MODE_1000BASEX:
+			data |= FIELD_PREP(YT922X_PORT_SDS_MODE_M,
+					   YT92XX_SERDES_MODE_1000BASEX);
+			break;
+		case PHY_INTERFACE_MODE_2500BASEX:
+			data |= FIELD_PREP(YT922X_PORT_SDS_MODE_M,
+					   YT92XX_SERDES_MODE_2500BASEX);
+			break;
+		case PHY_INTERFACE_MODE_USXGMII:
+			data |= FIELD_PREP(YT922X_PORT_SDS_MODE_M,
+					   YT92XX_SERDES_MODE_USXGMII);
+			break;
+		default:
+			return -EINVAL;
+		}
+		res = yt921x_intif_ext_write(priv, addr, YT922X_PORT_SDS_MODE,
+					     data);
+		if (res)
+			return res;
+		break;
+	default:
+		return -EINVAL;
+	}
+
+	return 0;
+}
+
+static void
+yt922x_phylink_mac_config(struct phylink_config *config, unsigned int mode,
+			  const struct phylink_link_state *state)
+{
+	struct dsa_port *dp = dsa_phylink_to_port(config);
+	struct yt921x_priv *priv = to_yt921x_priv(dp->ds);
+	int port = dp->index;
+	int res;
+
+	mutex_lock(&priv->reg_lock);
+	res = yt922x_port_config(priv, port, mode, state->interface);
+	mutex_unlock(&priv->reg_lock);
+
+	if (res)
+		dev_err(dp->ds->dev, "Failed to %s port %d: %i\n", "config",
+			port, res);
+}
+
